50:     struct WSAEvent
51:     {
52:     public:
53:         WSAEvent(struct pollfd* fd)
54:             : _fd(fd)
55:         {
56:             _event = WSACreateEvent();
57:         }
58: 
59:         WSAEvent(WSAEvent&& source) noexcept
60:         {
61:             _event = source._event;
62:             source._event = WSA_INVALID_EVENT; // invalidate the event in the source
63:             _fd = source._fd;
