71:                 // socket will report states that aren't there.
72:                 if (_fd != nullptr && (int)_fd->fd != -1)
73:                     WSAEventSelect(_fd->fd, _event, 0);
74:                 WSACloseEvent(_event);
75:             }
76:         }
