94:     //
95:     // That function could 'return WSAPoll(pfd, nfds, timeout);'
96:     // but WSAPoll is said to have weird behaviors on the internet
97:     // (the curl folks have had problems with it).
98:     //
99:     // So we make it a select wrapper
100:     //
101:     // UPDATE: WSAPoll was fixed in Windows 10 Version 2004
102:     //
103:     // The optional "event" is set to nullptr if it wasn't signaled.
104:     int poll(struct pollfd* fds, nfds_t nfds, int timeout, void** event)
105:     {
106: #ifdef _WIN32
107: 
108:         if (event && *event)
109:         {
110:             HANDLE interruptEvent = reinterpret_cast<HANDLE>(*event);
111:             *event = nullptr; // the event wasn't signaled yet
112: 
113:             if (nfds < 0 || nfds >= MAXIMUM_WAIT_OBJECTS - 1)
114:             {
115:                 WSASetLastError(WSAEINVAL);
116:                 return SOCKET_ERROR;
117:             }
118: 
119:             std::vector<WSAEvent> socketEvents;
120:             std::vector<HANDLE> handles;
121:             // put the interrupt event as first element, making it highest priority
122:             handles.push_back(interruptEvent);
123: 
124:             // create the WSAEvents for the sockets
125:             for (nfds_t i = 0; i < nfds; ++i)
126:             {
127:                 struct pollfd* fd = &fds[i];
128:                 fd->revents = 0;
129:                 if (fd->fd >= 0)
130:                 {
131:                     // create WSAEvent and add it to the vectors
132:                     socketEvents.push_back(std::move(WSAEvent(fd)));
133:                     HANDLE handle = socketEvents.back();
134:                     if (handle == WSA_INVALID_EVENT)
135:                     {
136:                         WSASetLastError(WSAENOBUFS);
137:                         return SOCKET_ERROR;
138:                     }
139:                     handles.push_back(handle);
140: 
141:                     // mapping
142:                     long networkEvents = 0;
143:                     if (fd->events & (POLLIN                               )) networkEvents |= FD_READ  | FD_ACCEPT | FD_CLOSE;
144:                     if (fd->events & (POLLOUT /*| POLLWRNORM | POLLWRBAND*/)) networkEvents |= FD_WRITE | FD_CONNECT;
145:                     //if (fd->events & (POLLPRI | POLLRDBAND               )) networkEvents |= FD_OOB;
146: 
147:                     if (WSAEventSelect(fd->fd, handle, networkEvents) != 0)
148:                     {
149:                         fd->revents = POLLNVAL;
150:                         socketEvents.pop_back();
151:                         handles.pop_back();
152:                     }
153:                 }
154:             }
155: 
156:             DWORD n = WSAWaitForMultipleEvents(static_cast<DWORD>(handles.size()), handles.data(), FALSE, timeout != -1 ? static_cast<DWORD>(timeout) : WSA_INFINITE, FALSE);
157: 
158:             if (n == WSA_WAIT_FAILED) return SOCKET_ERROR;
159:             if (n == WSA_WAIT_TIMEOUT) return 0;
160:             if (n == WSA_WAIT_EVENT_0)
161:             {
162:                 // the interrupt event was signaled
163:                 *event = reinterpret_cast<void*>(interruptEvent);
164:                 return 1;
165:             }
166: 
167:             int handleIndex = n - WSA_WAIT_EVENT_0;
168:             int socketIndex = handleIndex - 1;
169: 
170:             WSANETWORKEVENTS netEvents;
171:             int count = 0;
172:             // WSAWaitForMultipleEvents returns the index of the first signaled event. And to emulate WSAPoll()
173:             // all the signaled events must be processed.
174:             while (socketIndex < (int)socketEvents.size())
175:             {
176:                 struct pollfd* fd = socketEvents[socketIndex];
177: 
178:                 memset(&netEvents, 0, sizeof(netEvents));
179:                 if (WSAEnumNetworkEvents(fd->fd, socketEvents[socketIndex], &netEvents) != 0)
180:                 {
181:                     fd->revents = POLLERR;
182:                 }
183:                 else if (netEvents.lNetworkEvents != 0)
184:                 {
185:                     // mapping
186:                     if (netEvents.lNetworkEvents & (FD_READ  | FD_ACCEPT | FD_OOB | FD_CLOSE)) fd->revents |= POLLIN;
187:                     if (netEvents.lNetworkEvents & (FD_WRITE | FD_CONNECT                   )) fd->revents |= POLLOUT;
188:                     if (netEvents.lNetworkEvents & (FD_CLOSE                                )) fd->revents |= POLLHUP;
189: 
190:                     for (int i = 0; i < FD_MAX_EVENTS; ++i)
191:                     {
192:                         if (netEvents.iErrorCode[i] != 0)
193:                         {
194:                             fd->revents |= POLLERR;
195:                             break;
196:                         }
197:                     }
198: 
199:                     if (fd->revents != 0)
200:                     {
201:                         // only signaled sockets count
202:                         count++;
203:                     }
204:                 }
205:                 socketIndex++;
206:             }
207: 
208:             return count;
209:         }
210:         else
211:         {
212:             if (event && *event) *event = nullptr;
213: 
214:             socket_t maxfd = 0;
215:             fd_set readfds, writefds, errorfds;
216:             FD_ZERO(&readfds);
217:             FD_ZERO(&writefds);
218:             FD_ZERO(&errorfds);
219: 
220:             for (nfds_t i = 0; i < nfds; ++i)
221:             {
222:                 struct pollfd* fd = &fds[i];
223: 
224:                 if (fd->fd > maxfd)
225:                 {
226:                     maxfd = fd->fd;
227:                 }
228:                 if ((fd->events & POLLIN))
229:                 {
230:                     FD_SET(fd->fd, &readfds);
231:                 }
232:                 if ((fd->events & POLLOUT))
233:                 {
234:                     FD_SET(fd->fd, &writefds);
235:                 }
236:                 if ((fd->events & POLLERR))
237:                 {
238:                     FD_SET(fd->fd, &errorfds);
239:                 }
240:             }
241: 
242:             struct timeval tv;
243:             tv.tv_sec = timeout / 1000;
244:             tv.tv_usec = (timeout % 1000) * 1000;
245: 
246:             int ret = select(static_cast<int>(maxfd + 1), &readfds, &writefds, &errorfds, timeout != -1 ? &tv : NULL);
247: 
248:             if (ret < 0)
249:             {
250:                 return ret;
251:             }
252: 
253:             for (nfds_t i = 0; i < nfds; ++i)
254:             {
255:                 struct pollfd* fd = &fds[i];
256:                 fd->revents = 0;
257: 
258:                 if (FD_ISSET(fd->fd, &readfds))
259:                 {
260:                     fd->revents |= POLLIN;
261:                 }
262:                 if (FD_ISSET(fd->fd, &writefds))
263:                 {
264:                     fd->revents |= POLLOUT;
265:                 }
266:                 if (FD_ISSET(fd->fd, &errorfds))
267:                 {
268:                     fd->revents |= POLLERR;
269:                 }
270:             }
271:             return ret;
272:         }
273: #else
274:         if (event && *event) *event = nullptr;
275: 
276:         //
277:         // It was reported that on Android poll can fail and return -1 with
278:         // errno == EINTR, which should be a temp error and should typically
279:         // be handled by retrying in a loop.
280:         // Maybe we need to put all syscall / C functions in
281:         // a new IXSysCalls.cpp and wrap them all.
282:         //
283:         // The style from libuv is as such.
284:         //
285:         int ret = -1;
286:         do
287:         {
288:             ret = ::poll(fds, nfds, timeout);
289:         } while (ret == -1 && errno == EINTR);
290: 
291:         return ret;
292: #endif
293:     }
