45:                                 int timeoutMs,
46:                                 socket_t sockfd,
47:                                 const SelectInterruptPtr& selectInterrupt)
48:     {
49:         PollResultType pollResult = PollResultType::ReadyForRead;
50: 
51:         //
52:         // We used to use ::select to poll but on Android 9 we get large fds out of
53:         // ::connect which crash in FD_SET as they are larger than FD_SETSIZE. Switching
54:         // to ::poll does fix that.
55:         //
56:         // However poll isn't as portable as select and has bugs on Windows, so we
57:         // have a shim to fallback to select on those platforms. See
58:         // https://github.com/mpv-player/mpv/pull/5203/files for such a select wrapper.
59:         //
60:         nfds_t nfds = 1;
61:         struct pollfd fds[2];
62:         memset(fds, 0, sizeof(fds));
63: 
64:         fds[0].fd = sockfd;
65:         fds[0].events = (readyToRead) ? POLLIN : POLLOUT;
66: 
67:         // this is ignored by poll, but our select based poll wrapper on Windows needs it
68:         fds[0].events |= POLLERR;
69: 
70:         // File descriptor used to interrupt select when needed
71:         int interruptFd = -1;
72:         void* interruptEvent = nullptr;
73:         if (selectInterrupt)
74:         {
75:             interruptFd = selectInterrupt->getFd();
76:             interruptEvent = selectInterrupt->getEvent();
77: 
78:             if (interruptFd != -1)
79:             {
80:                 nfds = 2;
81:                 fds[1].fd = interruptFd;
82:                 fds[1].events = POLLIN;
83:             }
84:             else if (interruptEvent == nullptr)
85:             {
86:                 // Emulation mode: SelectInterrupt neither supports file descriptors nor events
87: 
88:                 // Check the selectInterrupt for requests before doing the poll().
89:                 if (readSelectInterruptRequest(selectInterrupt, &pollResult))
90:                 {
91:                     return pollResult;
92:                 }
93:             }
94:         }
95: 
96:         void* event = interruptEvent; // ix::poll will set event to nullptr if it wasn't signaled
97:         int ret = ix::poll(fds, nfds, timeoutMs, &event);
98: 
99:         if (ret < 0)
100:         {
101:             pollResult = PollResultType::Error;
102:         }
103:         else if (ret == 0)
104:         {
105:             pollResult = PollResultType::Timeout;
106:             if (selectInterrupt && interruptFd == -1 && interruptEvent == nullptr)
107:             {
108:                 // Emulation mode: SelectInterrupt neither supports fd nor events
109: 
110:                 // Check the selectInterrupt for requests
111:                 readSelectInterruptRequest(selectInterrupt, &pollResult);
112:             }
113:         }
114:         else if ((interruptFd != -1 && fds[1].revents & POLLIN) || (interruptEvent != nullptr && event != nullptr))
